let modo = flow.get("modo") || "automatico";
let percentualManual = flow.get("percentualManual");

if (percentualManual === undefined) {
    percentualManual = 50;
}

let tabela = flow.get("tabelaReferencia") || [
    { vazao: 20, percentual: 18 },
    { vazao: 40, percentual: 35 },
    { vazao: 60, percentual: 52 },
    { vazao: 80, percentual: 71 },
    { vazao: 100, percentual: 90 }
];

// Simulação da vazão de entrada da água na ETA em L/h
let vazao = 50 + 18 * Math.sin(Date.now() / 30000) + 4 * Math.sin(Date.now() / 9000);

function interpolarPercentual(q, tabela) {
    tabela = tabela
        .map(p => ({
            vazao: Number(p.vazao),
            percentual: Number(p.percentual)
        }))
        .filter(p => !isNaN(p.vazao) && !isNaN(p.percentual))
        .sort((a, b) => a.vazao - b.vazao);

    if (tabela.length < 2) {
        return 0;
    }

    if (q <= tabela[0].vazao) {
        return tabela[0].percentual;
    }

    if (q >= tabela[tabela.length - 1].vazao) {
        return tabela[tabela.length - 1].percentual;
    }

    for (let i = 0; i < tabela.length - 1; i++) {
        let q1 = tabela[i].vazao;
        let q2 = tabela[i + 1].vazao;
        let p1 = tabela[i].percentual;
        let p2 = tabela[i + 1].percentual;

        if (q >= q1 && q <= q2) {
            return p1 + ((q - q1) / (q2 - q1)) * (p2 - p1);
        }
    }

    return 0;
}

let percentual = 0;
let alarme = "Nenhum";
let bomba = "Liberada";

if (modo === "desligado") {
    percentual = 0;
    bomba = "Desligada";
    alarme = "Sistema desligado pelo operador";
}

else if (modo === "manual") {
    percentual = Number(percentualManual);
    bomba = "Liberada";
    alarme = "Nenhum";
}

else if (modo === "automatico") {
    percentual = interpolarPercentual(vazao, tabela);
    bomba = "Liberada";
    alarme = "Nenhum";
}

// Intertravamento automático por ausência de vazão de água
if (vazao <= 1) {
    percentual = 0;
    bomba = "Bloqueada";
    alarme = "Fluxo zero";
}

if (percentual > 100) percentual = 100;
if (percentual < 0) percentual = 0;

let corrente = 4 + (percentual / 100) * 16;
let vazaoBomba = (percentual / 100) * 26;

let modoFormatado = {
    automatico: "Automático",
    manual: "Manual",
    desligado: "Desligado"
}[modo] || modo;

msg.payload = {
    vazao: vazao.toFixed(2),
    percentual: percentual.toFixed(1),
    vazaoBomba: vazaoBomba.toFixed(2),
    corrente: corrente.toFixed(2),
    modo: modoFormatado,
    bomba: bomba,
    alarme: alarme,
    comunicacao: "Simulada"
};

return msg;

msg.topic = "Vazão de entrada da água";
msg.payload = Number(msg.payload.vazao);
return msg;

msg.topic = "Corrente 4-20 mA";
msg.payload = Number(msg.payload.corrente);
return msg;

let modo = msg.payload;

if (modo === "manual") {
    msg.payload = {
        groups: {
            show: ["Operação:Controle manual"]
        }
    };
} else {
    msg.payload = {
        groups: {
            hide: ["Operação:Controle manual"]
        }
    };
}

return msg;

let texto = msg.payload;

if (typeof texto !== "string") {
    msg.payload = {
        status: "erro",
        mensagem: "Arquivo CSV inválido."
    };
    return msg;
}

texto = texto.trim();

if (texto.length === 0) {
    msg.payload = {
        status: "erro",
        mensagem: "O arquivo CSV está vazio."
    };
    return msg;
}

let linhas = texto
    .split(/\r?\n/)
    .map(l => l.trim())
    .filter(l => l.length > 0);

if (linhas.length < 2) {
    msg.payload = {
        status: "erro",
        mensagem: "O CSV precisa conter cabeçalho e pelo menos uma linha de dados."
    };
    return msg;
}

let separador = linhas[0].includes(";") ? ";" : ",";

let cabecalho = linhas[0]
    .split(separador)
    .map(c => c.trim().toLowerCase());

let idxVazao = cabecalho.indexOf("vazao");
let idxPercentual = cabecalho.indexOf("percentual");

if (idxVazao === -1 || idxPercentual === -1) {
    msg.payload = {
        status: "erro",
        mensagem: "O cabeçalho deve conter as colunas: vazao e percentual."
    };
    return msg;
}

let tabela = [];

for (let i = 1; i < linhas.length; i++) {
    let colunas = linhas[i].split(separador).map(c => c.trim());

    let vazao = Number(colunas[idxVazao].replace(",", "."));
    let percentual = Number(colunas[idxPercentual].replace(",", "."));

    if (isNaN(vazao) || isNaN(percentual)) {
        msg.payload = {
            status: "erro",
            mensagem: "Erro na linha " + (i + 1) + ": vazão e percentual devem ser numéricos."
        };
        return msg;
    }

    if (percentual < 0 || percentual > 100) {
        msg.payload = {
            status: "erro",
            mensagem: "Erro na linha " + (i + 1) + ": percentual deve estar entre 0 e 100%."
        };
        return msg;
    }

    tabela.push({
        vazao: vazao,
        percentual: percentual
    });
}

if (tabela.length < 2) {
    msg.payload = {
        status: "erro",
        mensagem: "A tabela precisa ter pelo menos dois pontos para interpolação."
    };
    return msg;
}

tabela.sort((a, b) => a.vazao - b.vazao);

for (let i = 1; i < tabela.length; i++) {
    if (tabela[i].vazao === tabela[i - 1].vazao) {
        msg.payload = {
            status: "erro",
            mensagem: "Existem valores repetidos de vazão na tabela."
        };
        return msg;
    }
}

flow.set("tabelaReferencia", tabela);

msg.payload = {
    status: "ok",
    mensagem: "Tabela CSV importada com sucesso: " + tabela.length + " pontos carregados.",
    tabela: tabela,
    arquivo: msg.filename || "arquivo.csv"
};

return msg;

msg.topic = "Vazão da bomba dosadora";
msg.payload = Number(msg.payload.vazaoBomba);
return msg;

let pontos = msg.payload;

if (!Array.isArray(pontos)) {
    msg.payload = {
        status: "erro",
        mensagem: "Formato inválido da tabela manual.",
        tabela: []
    };
    return msg;
}

let tabela = [];

for (let i = 0; i < pontos.length; i++) {
    let vazao = Number(pontos[i].vazao);
    let percentual = Number(pontos[i].percentual);

    if (isNaN(vazao) || isNaN(percentual)) {
        msg.payload = {
            status: "erro",
            mensagem: "Erro no ponto " + (i + 1) + ": vazão e percentual devem ser numéricos.",
            tabela: []
        };
        return msg;
    }

    if (percentual < 0 || percentual > 100) {
        msg.payload = {
            status: "erro",
            mensagem: "Erro no ponto " + (i + 1) + ": percentual deve estar entre 0 e 100%.",
            tabela: []
        };
        return msg;
    }

    tabela.push({
        vazao: vazao,
        percentual: percentual
    });
}

if (tabela.length < 2) {
    msg.payload = {
        status: "erro",
        mensagem: "A tabela precisa ter pelo menos dois pontos para interpolação.",
        tabela: []
    };
    return msg;
}

tabela.sort((a, b) => a.vazao - b.vazao);

for (let i = 1; i < tabela.length; i++) {
    if (tabela[i].vazao === tabela[i - 1].vazao) {
        msg.payload = {
            status: "erro",
            mensagem: "Existem valores repetidos de vazão na tabela.",
            tabela: []
        };
        return msg;
    }
}

flow.set("tabelaReferencia", tabela);

msg.payload = {
    status: "ok",
    mensagem: "Tabela manual salva com sucesso: " + tabela.length + " pontos carregados.",
    tabela: tabela,
    origem: "manual"
};

return msg;
